CREATE OR REPLACE FUNCTION public.hub_output_file_boundary() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE project_code text; prefix text; BEGIN SELECT code INTO project_code FROM public.projects WHERE id=NEW.project_id; prefix:='projects/'||project_code||'/outputs/'||NEW.id::text||'/'; IF NEW.location IS NOT NULL THEN IF NEW.sha256 IS NULL OR NEW.file_name IS NULL THEN RAISE EXCEPTION 'Output file requires a fingerprint and filename'; END IF; IF NEW.location LIKE 'device:%' THEN IF NEW.kind<>'evidence_bundle' OR NEW.location IS DISTINCT FROM 'device:'||NEW.id::text||':'||NEW.sha256 THEN RAISE EXCEPTION 'Invalid device-only bundle identity'; END IF; ELSIF left(NEW.location,length(prefix))<>prefix OR left(substring(NEW.location from length(prefix)+1),65)<>NEW.sha256||'_' OR substring(NEW.location from length(prefix)+66) ~ '[/\\]' THEN RAISE EXCEPTION 'Output file must use its project, output and immutable fingerprint path'; END IF; END IF; IF NEW.kind='evidence_bundle' AND NEW.location IS NOT NULL AND EXISTS(SELECT 1 FROM public.project_items WHERE project_id=NEW.project_id AND item_kind='home_ref' AND unlinked_at IS NULL) AND NEW.location NOT LIKE 'device:%' THEN RAISE EXCEPTION 'Home-vault bundles must stay on the device'; END IF; RETURN NEW; END $$;
CREATE POLICY project_output_no_overwrite ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(bucket_id<>'evidence' OR name NOT LIKE 'projects/%') WITH CHECK(bucket_id<>'evidence' OR name NOT LIKE 'projects/%');
CREATE POLICY project_output_no_delete ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id<>'evidence' OR name NOT LIKE 'projects/%');
CREATE FUNCTION public.hub_download_event_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.event='output_downloaded' THEN IF NEW.actor_id IS DISTINCT FROM auth.uid() OR NOT public.can_access_project(auth.uid(),NEW.project_id) OR NOT EXISTS(SELECT 1 FROM public.project_outputs WHERE id::text=NEW.details->>'output_id' AND project_id=NEW.project_id AND sha256=NEW.details->>'sha256') THEN RAISE EXCEPTION 'Download log requires an accessible output and its recorded fingerprint'; END IF; NEW.created_at:=clock_timestamp(); SELECT display_name INTO NEW.actor_name FROM public.profiles WHERE id=auth.uid(); END IF; RETURN NEW; END $$;
CREATE TRIGGER download_event_guard BEFORE INSERT ON public.project_events FOR EACH ROW EXECUTE FUNCTION public.hub_download_event_guard();
REVOKE ALL ON FUNCTION public.hub_download_event_guard() FROM PUBLIC,anon,authenticated;
COMMENT ON FUNCTION public.hub_download_event_guard() IS 'Validates output identity for browser-reported verified downloads; it does not independently attest browser file verification.';